const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format((c||0)/100);
export async function studioAPI(path,data){const r=await fetch('/api/studio/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Could not complete the operation.');return v;}
function stylesheet(){if(!document.querySelector('[data-studio-css]')){const l=document.createElement('link');l.rel='stylesheet';l.href='/studio/designer.css';l.dataset.studioCss='';document.head.append(l);}}
const LANDSCAPE=['business-cards','brochures','yard-signs','vinyl-banners'];
function newDesign(product){const vehicle=!!product.views;return {productId:product.id,options:{sizeIndex:0,orientation:LANDSCAPE.includes(product.id)||vehicle||product.group==='Apparel'&&product.sizes[0].width>product.sizes[0].height?'landscape':'portrait',quantity:product.quantity[0],rounded:false,fold:product.folds[0]||'',sideCount:vehicle?product.views.length:product.group==='Apparel'?4:product.twoSided?2:1,values:Object.fromEntries(product.options.map(o=>[o.key,o.options[0].value])),selections:{},coupon:'',...(vehicle?{vehicleModel:product.vehicleModels?.[0]||'',vehicleColour:'white'}:{})},sides:Array.from({length:sideSlots(product)},()=>({background:'#ffffff',layers:[]})),assets:[],notes:''};}
// Older saved designs predate per-view vehicle sides; pad them so every view can be edited.
function normalise(design,product){while(design.sides.length<sideSlots(product))design.sides.push({background:design.options.vehicleColour==='black'?'#1e2023':'#ffffff',layers:[]});if(product.views)design.options.sideCount=product.views.length;return design;}
async function fontCSS(){let out='';for(const [name,path] of [['Inter','inter-latin.woff2'],['Vazirmatn','vazirmatn.woff2']]){try{const b=await (await fetch('/satin/fonts/'+path)).blob();const data=await dataURL(b);out+=`@font-face{font-family:'${name}';src:url('${data}') format('woff2');font-weight:100 900;}`;}catch{}}return out;}
const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});
export function priceHTML(q){return `<div><span>Subtotal</span><span>${money(q.subtotal)}</span></div>${q.discount?`<div><span>Discount</span><span>−${money(q.discount)}</span></div>`:''}<div><span>HST / tax</span><span>${money(q.tax)}</span></div><div class="total"><span>Estimated total</span><span>${money(q.total)}</span></div><div><span>Proposed deposit</span><span>${money(q.deposit)}</span></div><div><span>Balance</span><span>${money(q.balance)}</span></div>`;}
